    22→// Client defines the telemetry interface
    23→type Client interface {
    24→	TrackCommand(cmd *cobra.Command, strategy string, agent string, isEntireEnabled bool)
    25→	Close()
    26→}
    27→
    28→// NoOpClient is a no-op implementation for when telemetry is disabled
    29→type NoOpClient struct{}
    30→
    31→func (n *NoOpClient) TrackCommand(_ *cobra.Command, _ string, _ string, _ bool) {}
    32→func (n *NoOpClient) Close()                                                    {}
