    34→// silentLogger suppresses PostHog log output - expected for CLI best-effort telemetry
    35→type silentLogger struct{}
    36→
    37→func (silentLogger) Logf(_ string, _ ...interface{})   {}
    38→func (silentLogger) Debugf(_ string, _ ...interface{}) {}
    39→func (silentLogger) Warnf(_ string, _ ...interface{})  {}
    40→func (silentLogger) Errorf(_ string, _ ...interface{}) {}
