    42→// PostHogClient is the real telemetry client
    43→type PostHogClient struct {
    44→	client     posthog.Client
    45→	machineID  string
    46→	cliVersion string
    47→	mu         sync.RWMutex
    48→}
    49→
    50→// NewClient creates a new telemetry client based on opt-out settings.
    51→// The telemetryEnabled parameter comes from settings; nil means not configured (default to disabled).
    52→//
    53→//nolint:ireturn // Factory function - returns NoOpClient or PostHogClient based on settings
    54→func NewClient(version string, telemetryEnabled *bool) Client {
    55→	// Environment variable takes priority
    56→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
    57→		return &NoOpClient{}
    58→	}
    59→
    60→	// Check settings preference (nil = not set, default to disabled)
    61→	if telemetryEnabled == nil || !*telemetryEnabled {
    62→		return &NoOpClient{}
    63→	}
    64→
    65→	id, err := machineid.ProtectedID("entire-cli")
    66→	if err != nil {
    67→		return &NoOpClient{}
    68→	}
    69→
    70→	// Use a fast-timeout HTTP transport for telemetry - we don't want to block CLI exit
    71→	// transport := &http.Transport{
    72→	// 	DialContext: (&net.Dialer{
    73→	// 		Timeout: 100 * time.Millisecond,
    74→	// 	}).DialContext,
    75→	// 	TLSHandshakeTimeout:   100 * time.Millisecond,
    76→	// 	ResponseHeaderTimeout: 100 * time.Millisecond,
    77→	// }
    78→
    79→	client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
    80→		Endpoint: PostHogEndpoint,
    81→		// ShutdownTimeout:    100 * time.Millisecond, // Don't block CLI exit waiting for telemetry
    82→		// BatchUploadTimeout: 200 * time.Millisecond, // Fast timeout - telemetry is best-effort
    83→		// Transport:          transport,
    84→		Logger:       silentLogger{}, // Suppress warnings on timeout (expected)
    85→		DisableGeoIP: posthog.Ptr(true),
    86→		DefaultEventProperties: posthog.NewProperties().
    87→			Set("cli_version", version).
    88→			Set("os", runtime.GOOS).
    89→			Set("arch", runtime.GOARCH),
    90→	})
    91→	if err != nil {
    92→		return &NoOpClient{}
    93→	}
    94→
    95→	return &PostHogClient{
    96→		client:     client,
    97→		machineID:  id,
    98→		cliVersion: version,
    99→	}
   100→}
   101→
   102→// TrackCommand records the command execution
   103→func (p *PostHogClient) TrackCommand(cmd *cobra.Command, strategy string, agent string, isEntireEnabled bool) {
   104→	if cmd == nil {
   105→		return
   106→	}
   107→
   108→	// Skip hidden commands
   109→	if cmd.Hidden {
   110→		return
   111→	}
   112→
   113→	p.mu.RLock()
   114→	id := p.machineID
   115→	c := p.client
   116→	p.mu.RUnlock()
   117→
   118→	if c == nil {
   119→		return
   120→	}
   121→
   122→	// Collect flag names (not values) for privacy
   123→	var flags []string
   124→	cmd.Flags().Visit(func(flag *pflag.Flag) {
   125→		flags = append(flags, flag.Name)
   126→	})
   127→
   128→	selectedAgent := agent
   129→	if selectedAgent == "" {
   130→		selectedAgent = "auto"
   131→	}
   132→	props := posthog.NewProperties().
   133→		Set("command", cmd.CommandPath()).
   134→		Set("strategy", strategy).
   135→		Set("agent", selectedAgent).
   136→		Set("isEntireEnabled", isEntireEnabled)
   137→
   138→	if len(flags) > 0 {
   139→		props.Set("flags", strings.Join(flags, ","))
   140→	}
   141→
   142→	//nolint:errcheck // Best-effort telemetry, failures should not affect CLI
   143→	_ = c.Enqueue(posthog.Capture{
   144→		DistinctId: id,
   145→		Event:      "cli_command_executed",
   146→		Properties: props,
   147→	})
   148→}
   149→
   150→// Close flushes pending events
   151→func (p *PostHogClient) Close() {
   152→	p.mu.RLock()
   153→	c := p.client
   154→	p.mu.RUnlock()
   155→
   156→	if c != nil {
   157→		_ = c.Close()
   158→	}
   159→}
